// #132e12a27c52a9d24f10208d — в журнале доступа (/admin/access-log) колонка «פעולה» показывает только
// ивритские метки, без сырых ключей/латиницы. Кейс ACL-002. Только чтение — @prod-safe.
// Журнал показывает ограниченное число последних записей, поэтому проходим его диапазонами дат
// (по 7 дней; если ответ упёрся в лимит — по дням) от FIRST_DAY до сегодня.
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';

const FIRST_DAY = '2026-09-20'; // до первых записей журнала (самые ранние — 27.9.2026)
const LABELS: Record<string, string> = {
  regression_probe: 'רשומת בדיקה טכנית',
  create_simulation_from_template: 'יצירת סימולציה מתבנית',
  set_simulation_status: 'שינוי סטטוס סימולציה',
};

type Entry = { id: string; action: string; occurred_at: string };
type LogResponse = { entries: Entry[]; total?: number; limit?: number };

const iso = (d: Date) => d.toLocaleDateString('en-CA'); // YYYY-MM-DD, локальная дата
const addDays = (d: Date, n: number) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);

/** Фильтр «מתאריך»–«עד תאריך» → «סינון»; возвращает ответ RPC. */
async function filter(page: Page, from: string, to: string): Promise<LogResponse> {
  await page.locator('#access-log-from').fill(from);
  await page.locator('#access-log-to').fill(to);
  const res = page.waitForResponse((r) => r.url().includes('/rpc/admin_list_access_log') && r.request().method() === 'POST');
  await page.getByRole('button', { name: 'סינון', exact: true }).click();
  const r = await res;
  expect(r.ok(), `admin_list_access_log ${from}..${to}`).toBeTruthy();
  return (await r.json()) as LogResponse;
}

/** Тексты ячеек колонки «פעולה». */
async function actionCells(page: Page): Promise<string[]> {
  return page.evaluate(() => {
    const t = document.querySelector('main table');
    if (!t) return [];
    const heads = [...t.querySelectorAll('thead th')].map((h) => (h as HTMLElement).innerText.trim());
    const ai = heads.indexOf('פעולה');
    if (ai < 0) throw new Error('нет колонки «פעולה»: ' + heads.join('|'));
    return [...t.querySelectorAll('tbody tr')].map((r) => ((r.children[ai] as HTMLElement)?.innerText || '').trim());
  });
}

test.describe('Журнал доступа — метки действий на иврите (#132e12a27c52a9d24f10208d)', () => {
  test('ни в одной ячейке «פעולה» нет латиницы/snake_case; regression_probe, create_simulation_from_template, set_simulation_status — ивритские метки @desktop @prod-safe #132e12a27c52a9d24f10208d', async ({ asUser }) => {
    test.setTimeout(240_000);
    const page = await asUser('admin');
    await page.goto('/admin/access-log');
    await expect(page.getByRole('heading', { level: 1, name: 'רישום גישה' })).toBeVisible();

    const today = new Date();
    const ranges: [string, string][] = [];
    for (let d = new Date(FIRST_DAY + 'T00:00:00'); d <= today; d = addDays(d, 7)) {
      const end = addDays(d, 6);
      ranges.push([iso(d), iso(end > today ? today : end)]);
    }

    const seen = new Set<string>();
    const bad: string[] = [];
    let checkedRows = 0;

    const check = async (from: string, to: string, allowSplit: boolean) => {
      const data = await filter(page, from, to);
      const limit = data.limit ?? 200;
      if (allowSplit && data.entries.length >= limit && from !== to) {
        for (let d = new Date(from + 'T00:00:00'); iso(d) <= to; d = addDays(d, 1)) await check(iso(d), iso(d), false);
        return;
      }
      if (!data.entries.length) return;
      if (data.entries.length >= limit) {
        test.info().annotations.push({ type: 'warning', description: `${from}..${to}: ${limit}+ записей за день — проверены только последние ${limit}` });
      }
      // Таблица отрисовала ответ этого фильтра.
      await expect(page.locator('main table tbody tr')).toHaveCount(data.entries.length);
      const cells = await actionCells(page);
      checkedRows += cells.length;
      cells.forEach((c, i) => {
        if (/[A-Za-z_]/.test(c)) bad.push(`${from}..${to} строка ${i + 1}: «${c}»`);
      });
      // Конкретные ключи из тикета/реджекта → их ивритские метки в этой выборке.
      const actions = new Set(data.entries.map((e) => e.action));
      for (const [key, label] of Object.entries(LABELS)) {
        if (!actions.has(key)) continue;
        seen.add(key);
        expect(cells, `${from}..${to}: для ${key} нет метки «${label}»`).toContain(label);
        expect(cells).not.toContain(key);
      }
    };

    for (const [from, to] of ranges) await check(from, to, true);

    test.info().annotations.push({ type: 'checked', description: `${checkedRows} строк журнала, ${ranges.length} диапазонов` });
    // Источник: «מה רצוי» — «כל פעולה ברישום הגישה מוצגת בתווית בעברית».
    expect(bad, 'латиница / snake_case в колонке «פעולה»').toEqual([]);
    // Журнал неизменяем: записи этих действий есть с 27.9 и 4.10.2026.
    expect([...seen].sort()).toEqual(Object.keys(LABELS).sort());
  });
});
